    Usage: tools.mcp("api_search", query="calendar", top_k=10) or tools.mcp("api_fetch", method="GET", url="...", params="", body="")
    """
    url = "http://127.0.0.1:40573/mcp/0e17149da2e8ea7b35236a5e2f8fbfcf"
    payload = {"jsonrpc": "2.0", "id": 1, "method": "tools/call",
              "params": {"name": method_name, "arguments": args}}
    req = urllib.request.Request(url, data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json"}, method="POST")
    with urllib.request.urlopen(req, timeout=30) as r:
        data = json.loads(r.read().decode())
    if "error" in data:
        return "MCP ERROR: " + json.dumps(data["error"])[:2000]
    res = data.get("result", {})
    parts = []
    for c in res.get("content", []):
        if c.get("type") == "text":
            parts.append(c.get("text", ""))
    return "\n".join(parts)

