# 1. List all HubSpot deals
deals = []
after = None
for _ in range(10):
    params = json.dumps({"limit": 100, "properties": "dealname,dealstage,pipeline,amount,closedate,dealtype"})
    if after:
        params = json.dumps({"limit": 100, "after": after, "properties": "dealname,dealstage,pipeline,amount,closedate,dealtype"})
    r = j(tools.mcp("api_fetch", method="GET", url="https://api.hubapi.com/crm/v3/objects/deals", params=params, body=None))
    res = r.get("results", [])
    if isinstance(res, str):
        res = json.loads(res)
    deals.extend(res)
    after = None
    pg = r.get("paging", {})
    if isinstance(pg, str):
        pg = json.loads(pg)
    nxt = pg.get("next", {})
    if isinstance(nxt, dict):
        after = nxt.get("after")
    if not after:
        break
print("DEALS FOUND:", len(deals))
for d in deals:
    p = d.get("properties", {})
    print("-", p.get("dealname"), "|", p.get("dealstage"), "|", p.get("pipeline"), "|", p.get("amount"), "| dealId=", d.get("id"))
json.dump(deals, open("deals.json", "w"))

